;
; File offset $40000-$43FFF (16 KB); mapped $4000-$7FFF when bank reg = 16.
;
; RST $10 banked-call convention: LD HL,(bank<<8)|fn_idx ; RST $10.
; Function pointer table at $4001 (2 entries): fn0=$4005, fn1=$400F.
; Called from: bank4/$409C via LD HL,$1000; RST $10.
; fn0 $4005, fn1 $400F, fn2 $6ECD (per prior analysis).
;
; DISASSEMBLY METHOD: linear sweep from $4005. The raw bytes in each line
; comment [..] are authoritative and byte-exact vs terry.gbc; mnemonics
; describe them. NOTE embedded DATA / jump tables (if any) are decoded as
; spurious instructions by linear sweep -- trust the [hex] there, not the
; mnemonic. Operands are literal $hex: absolute addresses for JP/CALL/JR;
; LDH shows the low byte n (implied page $FF00+n).
; ============================================================================

SECTION "Bank 16", ROMX[$4000], BANK[16]

